cd /workspace && python3 -c "
import json
got = json.load(open('/tmp/out.json'))
want = json.loads(open('/workspace/examples.json').read())[0]['expected']
def flat(o, p=''):
    if isinstance(o, dict):
        for k in sorted(o): yield from flat(o[k], p+'/'+k)
    elif isinstance(o, list):
        for i,v in enumerate(o): yield from flat(v, p+'/%d'%i)
    else: yield p, o
g = dict(flat(got)); w = dict(flat(want))
for k in sorted(set(g)|set(w)):
    if g.get(k) != w.get(k): print('DIFF', k, g.get(k), w.get(k))
print('done')
"
